import java.util.*;class Solution{public List<Integer> findSubstring(String s,String[]w){List<Integer>o=new ArrayList<>();if(w.length==0)return o;int L=w[0].length(),k=w.length;Map<String,Integer>need=new HashMap<>();for(String x:w)need.merge(x,1,Integer::sum);for(int off=0;off<L;off++){Map<String,Integer>have=new HashMap<>();int l=off,c=0;for(int r=off;r+L<=s.length();r+=L){String x=s.substring(r,r+L);if(!need.containsKey(x)){have.clear();c=0;l=r+L;continue;}have.merge(x,1,Integer::sum);c++;while(have.get(x)>need.get(x)){String y=s.substring(l,l+L);have.put(y,have.get(y)-1);l+=L;c--;}if(c==k){o.add(l);String y=s.substring(l,l+L);have.put(y,have.get(y)-1);l+=L;c--;}}}return o;}}
